+      font-size: clamp(1.8rem, 3vw, 2.5rem);
+      line-height: 1.1;
+    }
+
+    .intro {
+      margin: 12px 0 0;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.6;
+    }
+
+    form {
+      margin-top: 28px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 16px;
+      margin-bottom: 24px;
+    }
+
+    .field-label {
+      font-size: 1.05rem;
+      font-weight: 700;
+      line-height: 1.5;
+    }
+
+    .radio-group {
+      display: grid;
+      gap: 12px;
+    }
+
+    .radio-option {
+      display: flex;
+      align-items: center;
+      gap: 14px;
+      padding: 16px 18px;
+      border: 1px solid rgba(148, 163, 184, 0.28);
+      border-radius: 18px;
+      background: rgba(255, 255, 255, 0.78);
+      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+      cursor: pointer;
+    }
+
+    .radio-option:hover {
+      border-color: rgba(37, 99, 235, 0.42);
+      box-shadow: 0 10px 30px rgba(37, 99, 235, 0.12);
+      transform: translateY(-1px);
+    }
+
+    .radio-option:focus-within {
+      border-color: var(--primary);
+      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.15);
+    }
+
+    .radio-option input[type="radio"] {
+      width: 20px;
+      height: 20px;
+      margin: 0;
+      accent-color: var(--primary);
+      flex: 0 0 auto;
+    }
+
+    .radio-copy {
+      display: grid;
+      gap: 2px;
+    }
+
+    .radio-title {
+      font-weight: 600;
+    }
+
+    .radio-description {
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    .actions {
+      display: flex;
+      align-items: center;
+      gap: 16px;
+      flex-wrap: wrap;
+    }
+
+    .submit-button {
+      border: 0;
+      border-radius: 999px;
+      background: linear-gradient(135deg, var(--primary), var(--primary-strong));
+      color: #fff;
+      padding: 14px 22px;
+      font: inherit;
+      font-weight: 700;
+      cursor: pointer;
+      box-shadow: 0 16px 40px rgba(37, 99, 235, 0.28);
+      transition: transform 160ms ease, box-shadow 160ms ease;
+    }
+
+    .submit-button:hover {
+      transform: translateY(-1px);
+      box-shadow: 0 18px 42px rgba(37, 99, 235, 0.34);
+    }
+
+    .submit-button:focus-visible {
+      outline: 3px solid rgba(37, 99, 235, 0.28);
+      outline-offset: 3px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+    }
+
+    @media (max-width: 600px) {
+      .card {
+        padding: 24px;
+      }
+
+      .radio-option {
+        align-items: flex-start;
+      }
+    }
+  </style>
+</head>
+<body>
+  <div id="app"></div>
+  <script>
+    const notificationOptions = [
+      {
+        id: "email",
+        value: "Email",
+        description: "Receive updates in your inbox."
+      },
+      {
+        id: "sms",
+        value: "SMS",
+        description: "Get quick text message alerts."
+      },
+      {
+        id: "push-notifications",
+        value: "Push Notifications",
+        description: "Stay informed with app notifications."
+      }
+    ];
+
+    const RadioOption = ({ id, value, description }) => `
+      <label class="radio-option" for="${id}">
+        <input type="radio" id="${id}" name="notificationPreference" value="${value}" required />
+        <span class="radio-copy">
+          <span class="radio-title">${value}</span>
+          <span class="radio-description">${description}</span>
+        </span>
+      </label>
+    `;
+
+    const FormField = ({ question, options }) => `
+      <div class="form-field">
+        <div class="field-label" id="notification-question">${question}</div>
+        <div class="radio-group" role="radiogroup" aria-labelledby="notification-question">
+          ${options.map((option) => RadioOption(option)).join("")}
+        </div>
+      </div>
+    `;
+
+    const NotificationPreferenceForm = () => `
+      <form id="notification-form">
+        ${FormField({
+          question: "How do you prefer to receive notifications?",
+          options: notificationOptions
+        })}
+        <div class="actions">
+          <button class="submit-button" type="submit">Submit</button>
+          <p class="status" id="form-status" aria-live="polite"></p>
+        </div>
+      </form>
+    `;
+
+    const App = () => `
+      <main class="page-shell">
+        <section class="card" aria-labelledby="page-title">
+          <p class="eyebrow">Preferences</p>
+          <h1 id="page-title">Choose your notification style</h1>
+          <p class="intro">
+            Select the one channel you want us to use for updates and account activity.
+          </p>
+          ${NotificationPreferenceForm()}
+        </section>
+      </main>
+    `;
+
+    document.getElementById("app").innerHTML = App();
+
+    document.getElementById("notification-form").addEventListener("submit", (event) => {
+      event.preventDefault();
+      const formData = new FormData(event.currentTarget);
+      const choice = formData.get("notificationPreference");
+      const status = document.getElementById("form-status");
+      status.textContent = choice
+        ? `Preference saved: ${choice}.`
+        : "Please choose one notification method.";
+    });
+  </script>
+</body>
+</html>
*** End Patch
